-- ============================================================
-- SEED EXT 5: Módulo 18 — Nominalization (ex 175-248)
-- Novos tópicos: nominalizations em TOEFL essays avançados,
-- chains of nominalizations, nominalization for emphasis,
-- academic abstracts com nominalizations
-- ============================================================
DO $$
DECLARE cid TEXT;
BEGIN
  SELECT id INTO cid FROM contents WHERE id = 'nominalization';
  IF cid IS NULL THEN RAISE EXCEPTION 'Módulo nominalization não encontrado'; END IF;

  INSERT INTO exercises (content_id, block_number, exercise_number, type, question, answer, options, explanation, difficulty) VALUES

  -- BLOCK 51: Nominalization de frases verbais complexas
  (cid,51,175,'gap_fill','The rapid _____ (expand) of _____ (access) to _____ (educate) has been one of _____ most significant _____ (achieve) of _____ postwar development era.','expansion / access / education / the / achievements / the',NULL,'Three nominalizations: expansion (expand), access (access), education (educate), achievement (achieve).','medium'),
  (cid,51,176,'gap_fill','The _____ (fail) of _____ (negotiate) parties _____ (reach) an agreement within the stipulated timeframe _____ (necessitate) a _____ (revisit) of the entire framework.','failure / negotiating / to reach / necessitated / revisiting',NULL,'Nominalization "failure" + gerund "negotiating" + infinitive "to reach" + "revisiting."','hard'),
  (cid,51,177,'gap_fill','_____ (require) that institutions _____ (demonstrate) their _____ (commit) to equity through specific _____ (measure) has proven more effective than mere _____ (encourage).','requiring / demonstrate / commitment / measures / encouragement',NULL,'Gerund "requiring" as subject + nominalization chains: commitment/measures/encouragement.','hard'),
  (cid,51,178,'multiple_choice','Which sentence MOST effectively uses nominalization for academic style?','The implementation of the new framework led to a significant reduction in administrative complexity.','["They implemented the new framework and this reduced administrative complexity significantly.","After the new framework was implemented, administrative complexity was reduced significantly.","The implementation of the new framework led to a significant reduction in administrative complexity.","When they implemented the new framework, it significantly reduced administrative complexity."]','Nominalization: "implementation" (← implement) + "reduction" (← reduce) = most academic/formal.','easy'),
  (cid,51,179,'gap_fill','A _____ (thorough/examine) of _____ evidence _____ (require) both a _____ (consider) of _____ extent to which _____ (exist) _____ (study) _____ (replicate/passive) and _____ (assess) of _____ quality of _____ _____ (methodology) _____ (employ/passive).','thorough examination / the / requires / consideration / the / existing / studies / have been replicated / an assessment / the / the methodologies / employed',NULL,'Dense academic nominalization chain typical of research reviews.','hard'),

  -- BLOCK 52: Transformando frases verbais em nominalizações
  (cid,52,180,'gap_fill','Rewrite as nominalization: "When researchers collected data, they found the results were inconsistent." → "_____ of _____ revealed _____ in _____ results."','The collection / data / inconsistencies / the',NULL,'collect → collection; inconsistent → inconsistencies; nominalization transforms the clause into a noun phrase.','medium'),
  (cid,52,181,'gap_fill','Rewrite as nominalization: "Because the policy failed, confidence in the government declined." → "The _____ of _____ led to _____ in public _____ in _____ government."','failure / the policy / a decline / confidence / the',NULL,'"Failure" (← fail) + "decline" (← declined) + "confidence" (← confident/confidence).','medium'),
  (cid,52,182,'gap_fill','Rewrite as nominalization: "If we implement reforms quickly, we will improve outcomes." → "_____ _____ of reforms _____ facilitate _____ in outcomes."','Rapid / implementation / would / improvement',NULL,'"Implementation" (← implement) + "improvement" (← improve).','medium'),
  (cid,52,183,'multiple_choice','Which nominalization is INCORRECT?','The increasing of prices led to demand reduction.','["The increase in prices led to demand reduction.","Price increases led to a reduction in demand.","Rising prices led to reduced demand.","The increasing of prices led to demand reduction."]','"The increasing of" = incorrect; the noun form is "increase" not "increasing" in this context.','hard'),
  (cid,52,184,'gap_fill','The _____ (achieve) of _____ (sustain) economic _____ (grow) without _____ (worsen) _____ (distribute) _____ (inequal) remains the central challenge of _____ (develop) _____ (politic).','achievement / sustainable / growth / worsening / distributional / inequality / development / policy',NULL,'Chain of nominalizations across an entire academic sentence.','hard'),

  -- BLOCK 53: Nominalization em academic abstracts
  (cid,53,185,'production','[TOEFL Writing — 100 words] Write an academic abstract using nominalization extensively. Topic: the effect of income inequality on educational outcomes.','',NULL,'This paper examines the relationship between income inequality and educational attainment across a panel of forty-two countries over the period 1990-2020. Through the application of fixed-effects regression analysis and the use of instrumental variables to address endogeneity concerns, we find robust evidence of a significant negative association between inequality and average years of schooling. The examination of distributional effects reveals that the primary mechanism of transmission operates through the deterioration of access to high-quality education for lower-income populations rather than through a general reduction in educational investment. These findings have direct implications for the design of educational finance reform and suggest the importance of redistributive investment as a complement to aggregate spending increases.','hard'),
  (cid,53,186,'gap_fill','This study _____ (examine) _____ (contribute) of _____ (regulate) to _____ (reduce) in _____ (consume) of _____ (harm) substances by _____ (use) of _____ (compare) _____ (analyse) of _____ (intervene) across 24 countries.','examines / the contribution / regulation / the reduction / the consumption / harmful / the use / a comparative / analysis / interventions',NULL,'Abstract-style nominalization sentence covering the study''s methodology and topic.','hard'),
  (cid,53,187,'gap_fill','The _____ (observe) of _____ (diverge) between _____ (predict) and _____ (actual/observe) _____ (out/come) led to _____ (reconsider) of _____ theoretical _____ (frame) underlying _____ original _____ (hypothesize).','observation / divergence / predicted / actually observed / outcomes / a reconsideration / the / framework / the / hypothesis',NULL,'Academic chain: observation of divergence between predicted and observed outcomes.','hard'),

  -- BLOCK 54: Nominalization para emphasis e agência
  (cid,54,188,'gap_fill','The government''s _____ (delay) in _____ (respond) to early warning signs has been _____ (wide) _____ (criticize/passive); _____ (subsequent/fail) to _____ (act) _____ (compound) the initial damage.','delay / responding / widely / criticized / the subsequent failure / act / compounded',NULL,'"Delay" + "responding" (gerund) + "failure" + "act" = nominalization with agency clarity.','hard'),
  (cid,54,189,'gap_fill','The _____ (refuse) of _____ (dominant) _____ (nation) _____ (engage) in _____ (good faith) _____ (negotiate) _____ (significantly/impair) _____ (prospect) for _____ (reach) an _____ (agree).','refusal / dominant / nations / to engage / good-faith / negotiations / significantly impaired / the prospects / reaching / agreement',NULL,'Dense nominalization: refusal to engage in negotiations, prospects for reaching an agreement.','hard'),
  (cid,54,190,'multiple_choice','Which sentence uses nominalization MOST effectively to focus on the PROCESS rather than the agent?','The gradual erosion of trust between communities made effective cooperation increasingly difficult.','["As trust between communities gradually eroded, they found it increasingly difficult to cooperate effectively.","Gradually, as trust eroded between communities, effective cooperation became increasingly difficult.","The gradual erosion of trust between communities made effective cooperation increasingly difficult.","Communities gradually stopped trusting each other, making cooperation difficult."]','"The gradual erosion of trust" = nominalization puts the process (erosion) in subject position, backgrounding the agents.','medium'),
  (cid,54,191,'gap_fill','The _____ (coexist) of _____ (high/grow) _____ (inequal) and _____ (rapid/expand) _____ (consume) among _____ (elite) _____ (group) _____ (create) _____ conditions for _____ (eventual/erode) of _____ (social/cohese).','coexistence / rapidly growing / inequality / rapidly expanding / consumption / elite / groups / creates / the / the eventual erosion / social cohesion',NULL,'Abstract nominalization chain: coexistence of inequality and consumption → erosion of social cohesion.','hard'),

  -- BLOCK 55: TOEFL Reading avançado com nominalizations
  (cid,55,192,'multiple_choice','[TOEFL Reading] "The implementation of stricter environmental regulations led to a significant reduction in industrial pollution." What are the two nominalizations?','"Implementation" (← implement) and "reduction" (← reduce).','["''environmental'' and ''industrial''","''Implementation'' (← implement) and ''reduction'' (← reduce).","''regulations'' and ''pollution''","''stricter'' and ''significant''"]','Nominalizations convert verbs to nouns: implement → implementation, reduce → reduction.','easy'),
  (cid,55,193,'gap_fill','[TOEFL Reading] Rewrite using nominalizations: "The fact that states cooperated enhanced the possibility that they could reach a settlement." → "_____ _____ enhanced _____ _____ of _____ _____ _____ ."','Interstate cooperation / enhanced / the prospect / of / successful / settlement / the likelihood of a negotiated settlement',NULL,'"Cooperation" (← cooperate) + "prospect/likelihood" + "settlement" (← settle).','hard'),
  (cid,55,194,'multiple_choice','[TOEFL Reading] "The deterioration of public services has eroded confidence in the state." The nominalization "deterioration" is used because:','It allows the sentence to treat the process of services getting worse as the grammatical subject, without attributing agency to anyone.','["It is a synonym for ''failure''","It allows the sentence to treat the process of services getting worse as the grammatical subject, without attributing agency to anyone.","It makes the sentence shorter","It is more polite than the verb form"]','Nominalization: "the deterioration" = depersonalized subject that avoids blaming a specific actor.','medium'),
  (cid,55,195,'gap_fill','[TOEFL Reading] Nominalize the verbs in brackets: "The _____ (persist) of _____ (conflict) despite _____ (negotiate) _____ (indicate) _____ (deep) _____ (structur/root) _____ (tension) that _____ (short-term/intervene) _____ (unlikely) _____ (resolve)."','persistence / conflict / negotiations / indicates / deeply / structural / tensions / short-term interventions are unlikely to resolve',NULL,'Dense nominalization chain characteristic of academic analysis texts.','hard'),

  -- BLOCK 56: TOEFL Speaking avançado
  (cid,56,196,'production','[TOEFL Speaking — 45s] Summarize a reading on the benefits of urban planning using nominalization.','',NULL,'The reading makes a comprehensive case for the contribution of strategic urban planning to the long-term sustainability and livability of cities. According to the reading, the application of evidence-based planning principles — including the prioritization of mixed-use development, the integration of green space into residential areas, and the investment in public transportation infrastructure — produces significant improvements in a range of outcome indicators. The reading presents evidence of the association between compact, transit-oriented urban forms and reductions in per capita energy consumption and carbon emissions. It also highlights the contribution of adequate provision of affordable housing to the preservation of socioeconomic diversity in cities and to the prevention of the displacement of lower-income populations that has accompanied urban regeneration in many cases. The reading concludes that the neglect of strategic urban planning in favor of market-led development has generated costs — in congestion, environmental degradation, and social polarization — whose remediation is far more expensive than the prevention of these problems through adequate investment in planning capacity would have been.','hard'),

  -- BLOCK 57: TOEFL Writing avançado
  (cid,57,197,'production','[TOEFL Writing — 200 words] Write a paragraph on economic development and governance using nominalization throughout.','',NULL,'The relationship between governance quality and economic development has been the subject of extensive investigation, and there is now substantial evidence of a significant positive association between institutional effectiveness and long-term growth performance. The accumulation of physical capital, while necessary for development, appears insufficient without the simultaneous development of institutional capacity: the enforcement of property rights, the administration of justice, and the provision of public goods. The deterioration of governance quality tends to undermine private investment by increasing the perception of uncertainty and by eroding confidence in the protection of contractual agreements. The experience of a number of countries that achieved rapid economic development under relatively authoritarian governance — the East Asian developmental states of the latter twentieth century — has been cited as evidence against a necessary relationship between democracy and growth, but the consolidation of democratic institutions in these countries as development proceeded suggests a longer-term complementarity. The measurement of governance, while methodologically complex, has improved substantially with the development of composite indicators that capture multiple dimensions of institutional performance. The interpretation of cross-national evidence on governance and development requires careful attention to the direction of causality, since economic success itself generates resources for institutional improvement, making the identification of independent governance effects challenging.','hard'),
  (cid,57,198,'production','[TOEFL Writing — 200 words] Write a paragraph on technological innovation and inequality using nominalization chains.','',NULL,'The acceleration of technological innovation has generated profound transformations in the distribution of economic gains, and the analysis of these distributional consequences is essential for understanding the political tensions associated with technological change. The concentration of the returns to innovation in the hands of those with the skills, capital, and network connections to capture them has contributed to a widening of income and wealth inequality in many high-income countries since the 1980s. The displacement of workers from routine tasks — both physical and cognitive — through automation has been a significant driver of wage stagnation among workers in the middle of the skill distribution, contributing to the hollowing out of employment in occupational categories that previously provided stable, well-compensated work for workers without post-secondary credentials. The relationship between technological change and inequality is not, however, a simple or deterministic one: the direction and magnitude of the distributional consequences of innovation depend significantly on the institutional context in which technology is deployed, including the strength of labor market institutions, the generosity of social insurance, the quality of educational investment, and the progressivity of the tax and transfer system. The deterioration of these institutional buffers in many countries over recent decades has amplified the inequality-generating effects of technological change beyond what the technology itself would have produced in a more supportive institutional environment.','hard'),

  -- BLOCK 58: Final
  (cid,58,199,'production','[TOEFL Writing — 200 words] Write a paragraph on migration and social integration using nominalization throughout.','',NULL,'The integration of migrants into receiving societies is a complex, multi-dimensional process whose success or failure has profound consequences for the wellbeing of migrants themselves and for the social cohesion of receiving communities. The development of social integration policy has been complicated by the absence of consensus about what successful integration actually means: whether it requires the assimilation of migrants into the cultural norms of the receiving society, the preservation of cultural distinctiveness within a framework of civic equality, or the negotiation of new hybrid identities that transform both migrant and receiving communities in the process. The evidence on the determinants of integration outcomes points to the importance of several factors, including the provision of language training, the recognition of foreign qualifications, the elimination of labor market discrimination, the availability of affordable housing in neighborhoods with adequate public services, and the quality of interaction between migrant and receiving-community children in educational settings. The concentration of migrants in disadvantaged neighborhoods — a pattern driven more by housing affordability constraints than by choice — tends to impede integration by reducing contact with native-born residents and concentrating disadvantage geographically. The politicization of immigration has complicated the design and implementation of effective integration policy in many countries, with the consequence that investment in integration support has often been insufficient relative to the scale of the challenge that rapid immigration creates.','hard'),
  (cid,58,200,'production','[TOEFL Speaking — 60s] Discuss the causes and consequences of the decline of manufacturing in high-income countries. Use nominalization throughout.','',NULL,'The deindustrialization of high-income economies — the long-term decline in the share of employment and output accounted for by manufacturing — has been one of the most significant structural transformations of the past half century, with profound consequences for the distribution of income, the geography of economic opportunity, and the political landscape. The acceleration of this transformation reflects the combination of two distinct processes: the automation of production, which has reduced the labor intensity of manufacturing without necessarily reducing output, and the offshoring of production to lower-wage economies, which represents a transfer of employment rather than its elimination in aggregate. The concentration of the costs of deindustrialization — unemployment, wage stagnation, community deterioration — in particular regions and among particular demographic groups, while the gains from cheaper consumer goods and higher corporate profitability have been more widely distributed, has generated the geographic and social polarization that has been associated with the rise of economic populism in several high-income countries. The reversal of this polarization requires not merely the restoration of manufacturing employment — whose return at the scale of previous decades is unlikely given the continuation of automation — but the development of alternative sources of economic security and opportunity for the communities and workers most affected by the transition. The design of policies adequate to this challenge — encompassing retraining, community investment, social insurance reform, and place-based economic development — represents one of the most significant governance challenges facing high-income democracies.','hard'),
  (cid,58,201,'production','[TOEFL Writing — Final 200 words] Write a conclusion on digital governance using nominalization throughout.','',NULL,'The analysis presented in this essay has argued that the governance of digital technology represents a challenge of a different order from previous regulatory challenges, requiring the development of new conceptual frameworks, institutional capacities, and international coordination mechanisms. The acceleration of technological change has outpaced the adaptation of governance structures that were designed for a different technological era, and the consequences of this lag — in terms of harms from algorithmic manipulation, surveillance, and market concentration — have been substantial and unevenly distributed. The establishment of effective digital governance requires the reconciliation of several values that exist in tension with one another: the promotion of innovation, the protection of privacy and autonomy, the maintenance of democratic information environments, and the preservation of market competition. The design of governance frameworks adequate to this reconciliation cannot be achieved through the application of existing regulatory approaches without modification; the characteristics of digital markets — network effects, zero marginal cost distribution, data as a production input — require the development of new regulatory tools and the adaptation of existing ones. The achievement of this governance transformation requires not merely technical expertise but political will, democratic legitimacy, and international coordination among jurisdictions whose regulatory ambitions and capacities differ substantially. The failure to achieve adequate governance of digital technology is not an inevitable outcome of technological development; it is a political choice whose consequences will compound over time if the required investment in governance capacity is not made.','hard')

  ON CONFLICT (content_id, block_number, exercise_number) DO NOTHING;
END $$;
